const QUIZ_ANSWERS = {
    q1: ['python', 'javascript'], // Correct answers for question 1
    q2: ['javascript', 'webassembly'], // Correct answers for question 2
    q3: ['rust', 'cpp', 'go'] // Correct answers for question 3
};

const QUIZ_QUESTIONS = {
    q1: 'Which of these are programming languages?',
    q2: 'Which languages run primarily in the browser?',
    q3: 'Which of these are compiled languages?'
};

// Initialize the quiz when DOM is ready
document.addEventListener('DOMContentLoaded', function() {
    const quizForm = document.getElementById('quizForm');
    quizForm.addEventListener('submit', handleQuizSubmit);
});

/**
 * Handles quiz form submission
 */
function handleQuizSubmit(event) {
    event.preventDefault();

    // Collect user answers
    const userAnswers = {
        q1: getCheckedValues('q1'),
        q2: getCheckedValues('q2'),
        q3: getCheckedValues('q3')
    };

    // Calculate results
    const results = calculateResults(userAnswers);

    // Display results
    displayResults(results);
}

/**
 * Gets all checked values for a question
 */
function getCheckedValues(questionName) {
    const checkboxes = document.querySelectorAll(`input[name="${questionName}"]:checked`);
    return Array.from(checkboxes).map(checkbox => checkbox.value);
}

/**
 * Calculates quiz results
 */
function calculateResults(userAnswers) {
    let totalCorrect = 0;
    const questionResults = [];

    for (let i = 1; i <= 3; i++) {
        const questionKey = `q${i}`;
        const correctAnswers = QUIZ_ANSWERS[questionKey];
        const userAnswer = userAnswers[questionKey];

        // Check if user answer matches correct answer (order doesn't matter)
        const isCorrect = arraysEqual(userAnswer, correctAnswers);

        if (isCorrect) {
            totalCorrect++;
        }

        questionResults.push({
            questionNumber: i,
            questionText: QUIZ_QUESTIONS[questionKey],
            isCorrect: isCorrect,
            userAnswer: userAnswer,
            correctAnswer: correctAnswers
        });
    }

    return {
        totalCorrect: totalCorrect,
        totalQuestions: 3,
        percentage: Math.round((totalCorrect / 3) * 100),
        questions: questionResults
    };
}

/**
 * Compares two arrays for equality (order-independent)
 */
function arraysEqual(arr1, arr2) {
    if (arr1.length !== arr2.length) return false;
    return arr1.sort().every((val, idx) => val === arr2.sort()[idx]);
}

/**
 * Displays quiz results
 */
function displayResults(results) {
    const quizForm = document.getElementById('quizForm');
    const resultsSection = document.getElementById('resultsSection');
    const resultsContent = document.getElementById('resultsContent');

    // Hide form and show results
    quizForm.style.display = 'none';
    resultsSection.style.display = 'block';

    // Build results HTML
    let resultsHTML = `
        <div class="result-summary" style="text-align: center; margin-bottom: 2rem; padding: 1rem; background-color: var(--bg-tertiary); border-radius: 8px;">
            <div style="font-size: 2rem; font-weight: bold; color: var(--accent-color); margin-bottom: 0.5rem;">
                ${results.totalCorrect} / ${results.totalQuestions}
            </div>
            <div style="font-size: 1.125rem; color: var(--text-secondary);">
                ${results.percentage}% Correct
            </div>
        </div>
    `;

    // Add individual question results
    results.questions.forEach(question => {
        const statusClass = question.isCorrect ? 'correct' : 'incorrect';
        const statusText = question.isCorrect ? '✓ Correct' : '✗ Incorrect';

        resultsHTML += `
            <div class="result-item ${statusClass}">
                <div class="result-title">Question ${question.questionNumber}: ${statusText}</div>
                <div style="font-size: 0.9rem; margin-bottom: 0.5rem; color: var(--text-secondary);">
                    ${question.questionText}
                </div>
                <div style="font-size: 0.875rem; margin-bottom: 0.3rem;">
                    <strong>Your answer:</strong> ${question.userAnswer.length > 0 ? question.userAnswer.join(', ') : 'No answer selected'}
                </div>
                <div style="font-size: 0.875rem;">
                    <strong>Correct answer:</strong> ${question.correctAnswer.join(', ')}
                </div>
            </div>
        `;
    });

    resultsContent.innerHTML = resultsHTML;

    // Scroll to results
    resultsSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
}
